package com.hibernate.ecommerce.controller;import com.hibernate.ecommerce.dto.OrderDTO;import com.hibernate.ecommerce.model.state;import com.hibernate.ecommerce.service.IOrderService;import jakarta.validation.Valid;import jakarta.validation.constraints.Positive;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.support.ServletUriComponentsBuilder;import java.net.URI;import java.util.List;@RestController@RequestMapping("/v1/api/order")public class OrderController {    private final IOrderService iOrderService;    public OrderController(IOrderService iOrderService) {        this.iOrderService = iOrderService;    }    @PostMapping("/insert")    public ResponseEntity<OrderDTO> insertOrder(@Valid @RequestBody OrderDTO dto){        OrderDTO saved = iOrderService.addOrder(dto);        URI location = ServletUriComponentsBuilder                .fromCurrentRequest()                .path("/{id}")                .buildAndExpand(saved.getId())                .toUri();        return ResponseEntity.created(location).body(saved);    }    @GetMapping("/search/{id}")    public ResponseEntity<OrderDTO> findOrderById(@PathVariable @Positive Long id){        return ResponseEntity.ok(iOrderService.findOrderById(id));    }    @GetMapping("/searchClient/{clientId}")    public ResponseEntity<List<OrderDTO>> findOrderByClient(@PathVariable @Positive Long clientId, @RequestParam(required = false)state state){        return ResponseEntity.ok(iOrderService.findOrderByClient(clientId, state));    }    @PutMapping("/changeState")    public ResponseEntity<OrderDTO> changeOrderState(@Valid @RequestBody OrderDTO dto){        return ResponseEntity.ok(iOrderService.changeState(dto));    }    @DeleteMapping("/delete/{id}")    public ResponseEntity<Void> deleteOrderById(@PathVariable @Positive Long id){        iOrderService.deleteOrder(id);        return ResponseEntity.noContent().build();    }}